package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.hq.app.rollup.Actor;
import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateHold {
    public void validate(@RequestBody HoldRequest request, Out<HoldChange> body, Out<Actor> actor)
            throws InvalidSheetRequestException {
        String user = request != null ? request.user() : null;
        LocalDate from = date(request != null ? request.from() : null);
        LocalDate to = date(request != null ? request.to() : null);
        if (from != null && to != null && to.isBefore(from)) {
            throw new InvalidSheetRequestException("A hold's to-date cannot be before its from-date");
        }
        body.set(new HoldChange(from, to, user));
        actor.set(new Actor(user));
    }

    private static LocalDate date(String typed) throws InvalidSheetRequestException {
        String raw = typed == null ? "" : typed.trim();
        if (raw.isEmpty()) return null;
        try {
            return LocalDate.parse(raw);
        } catch (DateTimeParseException e) {
            throw new InvalidSheetRequestException("Not a date (yyyy-mm-dd): " + raw);
        }
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateRetire {
    public void validate(@RequestBody RetireRequest request, Out<Retirement> body)
            throws InvalidSheetRequestException {
        String raw = request == null || request.from() == null ? "" : request.from().trim();
        LocalDate from = null;
        if (!raw.isEmpty()) {
            try {
                from = LocalDate.parse(raw);
            } catch (DateTimeParseException e) {
                throw new InvalidSheetRequestException("Not a date (yyyy-mm-dd): " + raw);
            }
        }
        body.set(new Retirement(from, request == null ? null : request.user()));
    }
}
package net.officefloor.hq.app.rollup;

/** Who makes a change, published by the change's validating step for the steps after it. */
public record Actor(String user) {
}
package net.officefloor.hq.app.rollup;

import net.officefloor.plugin.variable.Val;

/** Runs after the change's own audit lines: audits the figures it moved. */
public class RecordRollup {
    public void record(@Val RollupBefore before, @Val Actor actor, Rollup rollup) {
        rollup.record(before.sheetId(), before.snapshot(), actor.user());
    }
}
package net.officefloor.hq.app.rollup;

/** The sheet's figures as they were before the change. */
public record RollupBefore(String sheetId, Snapshot snapshot) {
}
package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.claim.Figures;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.settings.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import org.springframework.stereotype.Service;

/**
 * The figures the screen shows — each person's claimed and due-total, the sheet's claimed-total and
 * due-total, and each one's overdue-total and the sheet's — worked out as the screen does, so a change can audit the ones it moved: one ROLLUP
 * line per person whose figures changed (a new person counts as changed), then a TOTALS line when
 * the sheet's totals changed.
 */
@Service
public class Rollup {

    private static final BigDecimal ZERO = BigDecimal.ZERO.setScale(2);

    private final People people;
    private final Claims claims;
    private final Figures figures;
    private final Rates rates;
    private final Sheets sheets;
    private final Audit audit;
    private final Settings settings;

    public Rollup(People people, Claims claims, Figures figures, Rates rates, Sheets sheets, Audit audit, Settings settings) {
        this.people = people;
        this.claims = claims;
        this.figures = figures;
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
        this.settings = settings;
    }

    /** The sheet's figures now. A person's due-total is the sum of their counting claims' figures (a
     *  person's OPEN claims dated within a hold of theirs do not count, unless a statement binds them),
     *  n/a when there is no rate today and none has a figure, at most the sheet's cap (n/a is not
     *  capped); the sheet's skips the n/a ones, and its due and overdue totals leave out the single
     *  highest and lowest person's figure when three or more have one. */
    public Snapshot snapshot(String sheetId) {
        LocalDate today = sheets.today(sheetId);
        List<Claim> all = claims.onSheet(sheetId);
        Map<Long, Snapshot.PersonFigures> figuresOf = new LinkedHashMap<>();
        BigDecimal claimedTotal = ZERO;
        List<BigDecimal> dues = new ArrayList<>();

